using namespace std;

class Account {
public:
    Account(int, const string& = "anon");
    ~Account();
    int balance() const;
    void deposit(int);
    bool withdraw(int amount);
    static int count();
private:
    int value;
    string owner;
    static int alive;
};

int Account::alive = 0;

Account::Account(int x, const string& name) : value(x), owner(name) {
    ++alive;
    cout << "open " << owner << " " << value << endl;
}

Account::~Account() {
    --alive;
    cout << "close " << owner << " " << value << endl;
}

bool Account::withdraw(int amount) {
    if (amount > balance()) {
        cout << owner << " insufficient" << endl;
        return false;
    }
    value -= amount;
    return true;
}

int Account::balance() const { return value; }

void Account::deposit(int value) {
    this->value += value;
}

int Account::count() { return alive; }

