    {
        Account b(5);
        b.deposit(10);
        cout << "b=" << b.balance() << " count=" << Account::count() << endl;
        b.withdraw(50);
    }
    a.withdraw(30);
    a.deposit(7);
    cout << "a=" << a.balance() << " count=" << Account::count() << endl;
