class Matrix {
public:
    Matrix(int r = 2, int c = 2);
    Matrix(const Matrix& other);
    ~Matrix();
    int& at(int, int);
    const int& at(int, int) const;
    Matrix operator*(const Matrix&) const;
    Matrix& operator=(const Matrix& rhs);
    void print() const;
    int rows() const { return r; }
private:
    int r, c;
    int* data;
};

Matrix::Matrix(int r, int c) : r(r), c(c), data(new int[r * c]) {
    for (int i = 0; i < r * c; i++) data[i] = 0;
}

Matrix::Matrix(const Matrix& other) : r(other.r), c(other.c), data(new int[other.r * other.c]) {
    for (int i = 0; i < r * c; i++) data[i] = other.data[i];
}

Matrix::~Matrix() { delete[] data; }

int& Matrix::at(int i, int j) {
    cout << "[w]";
    return data[i * c + j];
}

const int& Matrix::at(int i, int j) const {
    return data[i * c + j];
}

Matrix Matrix::operator*(const Matrix& o) const {
    Matrix res(r, o.c);
    for (int i = 0; i < r; i++)
        for (int j = 0; j < o.c; j++) {
            int s = 0;
            for (int k = 0; k < c; k++) s += at(i, k) * o.at(k, j);
            res.data[i * o.c + j] = s;
        }
    return res;
}

Matrix& Matrix::operator=(const Matrix& rhs) {
    if (this == &rhs) return *this;
    delete[] data;
    r = rhs.r; c = rhs.c;
    data = new int[r * c];
    for (int i = 0; i < r * c; i++) data[i] = rhs.data[i];
    return *this;
}

void Matrix::print() const {
    for (int i = 0; i < r; i++) {
        for (int j = 0; j < c; j++) cout << at(i, j) << (j + 1 < c ? " " : "");
        cout << "\n";
    }
}

Matrix power(const Matrix& m, int n) {
    if (n == 1) return m;
    Matrix half = power(m, n / 2);
    Matrix sq = half * half;
    if (n % 2) sq = sq * m;
    return sq;
}

int main() {
