    fib.at(0, 0) = 1; fib.at(0, 1) = 1; fib.at(1, 0) = 1;
    cout << endl;
    const Matrix f10 = power(fib, 10);
    f10.print();
    cout << "fib(10)=" << f10.at(0, 1) << endl;
    Matrix m(2, 3);
    m = m;
    cout << "rows=" << m.rows() << endl;
    return 0;
}

