class Student;

class Course {
public:
    Course(const string& title, int cap = 3);
    ~Course();
    bool enroll(Student* s);
    void list() const;
    const string& name() const;
private:
    string title;
    Student** roster;
    int size, cap;
};

class Student {
public:
    explicit Student(const string&);
    void join(Course&);
    string name() const;
    int courses() const { return n; }
private:
    string nm;
    int n;
};

Student::Student(const string& name) : nm(name), n(0) {}

string Student::name() const { return nm; }

void Student::join(Course& c) {
    if (c.enroll(this)) {
        n++;
        cout << nm << " joined " << c.name() << endl;
    } else {
        cout << nm << " rejected by " << c.name() << endl;
    }
}

Course::Course(const string& title, int cap) : title(title), roster(new Student*[cap]), size(0), cap(cap) {}

Course::~Course() {
    cout << "~Course " << title << " with " << size << endl;
    delete[] roster;
}

const string& Course::name() const { return title; }

bool Course::enroll(Student* s) {
    for (int i = 0; i < size; i++)
        if (roster[i] == s) return false;
    if (size == cap) return false;
    roster[size++] = s;
    return true;
}

void Course::list() const {
    cout << title << ":";
    for (int i = 0; i < size; i++) cout << " " << roster[i]->name() << "(" << roster[i]->courses() << ")";
    cout << endl;
}

int main() {
    Student a("Ann"), b("Bob"), c("Cid");
    Course math("Math", 2);
    Course art("Art");
    a.join(math);
    b.join(math);
    c.join(math);
    a.join(math);
    c.join(art);
    a.join(art);
    math.list();
    art.list();
    return 0;
}

