class Node {
public:
    Node(int v, Node* l = nullptr, Node* r = nullptr);
    ~Node();
    int sum() const;
    int height() const;
    Node* insert(int);
    void inorder() const;
    int value() const;
    static int created;
    static int destroyed;
private:
    int val;
    Node* left;
    Node* right;
};

int Node::created = 0;
int Node::destroyed = 0;

int Node::height() const {
    int hl = left ? left->height() : 0;
    int hr = right ? right->height() : 0;
    return 1 + (hl > hr ? hl : hr);
}

Node::Node(int v, Node* l, Node* r) : val(v), left(l), right(r) { created++; }

Node::~Node() {
    delete left;
    delete right;
    destroyed++;
}

Node* Node::insert(int v) {
    Node*& slot = (v < val) ? left : right;
    if (slot == nullptr) {
        slot = new Node(v);
        return slot;
    }
    return slot->insert(v);
}

int Node::value() const { return val; }

int Node::sum() const {
    return val + (left ? left->sum() : 0) + (right ? right->sum() : 0);
}

void Node::inorder() const {
    if (left) left->inorder();
    cout << val << " ";
    if (right) right->inorder();
}

int main() {
    int arr[] = {50, 30, 70, 20, 40, 60, 80, 35, 45, 65};
    Node* root = new Node(arr[0]);
    for (int i = 1; i < 10; i++) {
        Node* p = root->insert(arr[i]);
        if (i % 3 == 0) cout << "inserted " << p->value() << endl;
    }
    root->inorder();
    cout << endl;
    cout << "sum=" << root->sum() << " height=" << root->height() << endl;
    delete root;
    cout << "created=" << Node::created << " destroyed=" << Node::destroyed << endl;
    return 0;
}

