class Stack {
public:
    Stack(int capacity = 4);
    ~Stack();
    void push(int);
    int pop();
    int& top();
    int top() const;
    bool empty() const;
    int size() const;
    Stack& operator<<(int x);
private:
    void grow();
    int* items;
    int n;
    int cap;
};

Stack& Stack::operator<<(int x) {
    push(x);
    return *this;
}

void Stack::push(int x) {
    if (n == cap) grow();
    items[n++] = x;
}

void Stack::grow() {
    int* bigger = new int[cap * 2];
    for (int i = 0; i < n; i++) bigger[i] = items[i];
    delete[] items;
    items = bigger;
    cap *= 2;
    cout << "(grow to " << cap << ")" << endl;
}

Stack::Stack(int capacity) : items(new int[capacity]), n(0), cap(capacity) {}

Stack::~Stack() {
    cout << "~Stack size=" << n << endl;
    delete[] items;
}

int Stack::pop() { return items[--n]; }
int& Stack::top() { return items[n - 1]; }
int Stack::top() const { return items[n - 1]; }
bool Stack::empty() const { return n == 0; }
int Stack::size() const { return n; }

int evalRPN(const char* tokens[], int count) {
    Stack st(2);
    for (int i = 0; i < count; i++) {
        char c = tokens[i][0];
        if (tokens[i][1] == '\0' && (c == '+' || c == '-' || c == '*' || c == '/')) {
            int b = st.pop();
            int a = st.pop();
            int r = 0;
            switch (c) {
                case '+': r = a + b; break;
                case '-': r = a - b; break;
                case '*': r = a * b; break;
                case '/': r = a / b; break;
            }
            st.push(r);
        } else {
            int v = 0, sign = 1, k = 0;
            if (tokens[i][0] == '-') { sign = -1; k = 1; }
            for (; tokens[i][k]; k++) v = v * 10 + (tokens[i][k] - '0');
            st.push(sign * v);
        }
    }
    return st.top();
}

int main() {
    const char* expr[] = {"3", "4", "+", "-2", "*", "7", "/", "10", "5", "-", "+"};
    cout << "rpn=" << evalRPN(expr, 11) << endl;
    Stack s;
    s << 1 << 2 << 3;
    s.top() += 40;
    const Stack& cs = s;
    cout << "top=" << cs.top() << " size=" << cs.size() << endl;
    while (!s.empty()) cout << s.pop() << " ";
    cout << endl;
    return 0;
}

