Car::Car(const string& m, Engine* e) : model(m), eng(nullptr), km(0) {
    cout << "Car " << model << endl;
    if (e) install(e);
}

Car::~Car() {
    cout << "~Car " << model << " km=" << km << endl;
    if (eng) eng->attach(nullptr);
}

void Car::install(Engine* e) {
    eng = e;
    e->attach(this);
}

void Car::drive(int km) {
    if (!eng) {
        cout << model << " has no engine" << endl;
        return;
    }
    this->km += eng->run(km);
}

int Car::odometer() const { return km; }
Engine* Car::engine() const { return eng; }

Engine::Engine(int power) : hp(power), hours(0), owner(nullptr) {}

Engine::~Engine() {
    cout << "~Engine hp=" << hp << " hours=" << hours << (owner ? " (still attached)" : "") << endl;
}

void Engine::attach(Car* c) { owner = c; }

int Engine::run(int distance) {
    int h = distance / 50 + (distance % 50 != 0);
    hours += h;
    return hp >= 100 ? distance : distance / 2;
}

int Engine::horsepower() const { return hp; }

