class Fraction {
public:
    Fraction(long long = 0, long long = 1);
    Fraction operator+(const Fraction&) const;
    Fraction operator*(const Fraction& other) const;
    Fraction& operator+=(const Fraction&);
    bool operator<(const Fraction&) const;
    bool operator==(const Fraction& rhs) const;
    void print() const;
    void print(const char* suffix) const;
    long long num() const;
    long long den() const;
private:
    static long long gcd(long long, long long);
    void normalize();
    long long n, d;
};

long long Fraction::gcd(long long a, long long b) {
    if (a < 0) a = -a;
    if (b < 0) b = -b;
    return b == 0 ? a : gcd(b, a % b);
}

Fraction::Fraction(long long numerator, long long denominator) : n(numerator), d(denominator) {
    normalize();
}

void Fraction::normalize() {
    if (d < 0) { n = -n; d = -d; }
    long long g = gcd(n, d);
    if (g > 1) { n /= g; d /= g; }
}

Fraction Fraction::operator+(const Fraction& o) const {
    return Fraction(n * o.d + o.n * d, d * o.d);
}

Fraction Fraction::operator*(const Fraction& o) const {
    return Fraction(n * o.n, d * o.d);
}

Fraction& Fraction::operator+=(const Fraction& o) {
    *this = *this + o;
    return *this;
}

bool Fraction::operator<(const Fraction& o) const { return n * o.d < o.n * d; }
bool Fraction::operator==(const Fraction& o) const { return n == o.n && d == o.d; }

void Fraction::print() const {
    if (d == 1) cout << n;
    else cout << n << "/" << d;
}

void Fraction::print(const char* suffix) const {
    print();
    cout << suffix;
}

long long Fraction::num() const { return n; }
long long Fraction::den() const { return d; }

Fraction harmonic(int k) {
    if (k == 0) return Fraction();
    return harmonic(k - 1) + Fraction(1, k);
}

int main() {
    Fraction arr[5] = {Fraction(3, -6), Fraction(2, 4), 7, Fraction(10, 4), Fraction(0, 5)};
    Fraction sum;
    for (int i = 0; i < 5; i++) {
        arr[i].print(i < 4 ? ", " : "\n");
        sum += arr[i];
    }
    sum.print(" = sum\n");
    Fraction* best = &arr[0];
    for (int i = 1; i < 5; i++)
        if (*best < arr[i]) best = arr + i;
    best->print(" is max\n");
    cout << (arr[0] * Fraction(-2) == Fraction(1) ? "yes" : "no") << endl;
    for (int k = 1; k <= 6; k++) harmonic(k).print(k < 6 ? " " : "\n");
    return 0;
}

#include <iostream>
#include <string>
