class Logger {
public:
    Logger(const string& prefix);
    ~Logger();
    Logger& log(const string&);
    Logger& log(int);
    Logger& log(const string& key, int value);
    int lines() const;
    static Logger* current;
private:
    string prefix;
    int count;
    Logger* previous;
};

class Inventory {
public:
    Inventory(int n);
    ~Inventory();
    int& operator[](int);
    int operator[](int) const;
    int total(int from = 0) const;
    int* find(int value);
private:
    int* slots;
    int n;
};

Logger* Logger::current = nullptr;

Logger::Logger(const string& prefix) : prefix(prefix), count(0), previous(current) {
    current = this;
    log("start");
}

Logger::~Logger() {
    log("lines", count + 1);
    current = previous;
}

Logger& Logger::log(const string& msg) {
    ++count;
    cout << prefix << ": " << msg << endl;
    return *this;
}

Logger& Logger::log(int v) {
    return log(to_string(v));
}

Logger& Logger::log(const string& key, int value) {
    return log(key + "=" + to_string(value));
}

int Logger::lines() const { return count; }

Inventory::Inventory(int n) : slots(new int[n]()), n(n) {
    Logger::current->log("inventory", n);
}

Inventory::~Inventory() {
    if (Logger::current) Logger::current->log("free inventory");
    delete[] slots;
}

int& Inventory::operator[](int i) { return slots[i]; }
int Inventory::operator[](int i) const { return slots[i]; }

int Inventory::total(int from) const {
    if (from >= n) return 0;
    return (*this)[from] + total(from + 1);
}

int* Inventory::find(int value) {
    for (int i = 0; i < n; i++)
        if (slots[i] == value) return slots + i;
    return nullptr;
}

int main() {
    Logger outer("main");
    {
        Logger inner("inner");
        Inventory inv(5);
        for (int i = 0; i < 5; i++) inv[i] = (i + 1) * (i + 1);
        Logger::current->log("total", inv.total()).log(inv.total(3));
        int* p = inv.find(9);
        if (p) *p = -9;
        int* q = inv.find(100);
        Logger::current->log(q == nullptr ? "100 missing" : "100 found");
        const Inventory& ci = inv;
        outer.log("slot2", ci[2]);
    }
    outer.log(outer.lines());
    return 0;
}

#include <iostream>
using namespace std;

class Grid {
public:
    Grid(int rows, int cols, const char* pattern);
    ~Grid();
    int countRegions();
    int largest() const;
    char get(int r, int c) const;
    void show() const;
private:
    int fill(int r, int c, char mark);
    bool inside(int, int) const;
    int R, C;
    char** cells;
    int best;
};

int Grid::countRegions() {
    int regions = 0;
    best = 0;
    for (int r = 0; r < R; r++)
        for (int c = 0; c < C; c++)
            if (cells[r][c] == '#') {
                char mark = 'a' + regions;
                int size = fill(r, c, mark);
                if (size > best) best = size;
                regions++;
            }
    return regions;
}

int Grid::fill(int r, int c, char mark) {
    if (!inside(r, c) || cells[r][c] != '#') return 0;
    cells[r][c] = mark;
    return 1 + fill(r + 1, c, mark) + fill(r - 1, c, mark)
             + fill(r, c + 1, mark) + fill(r, c - 1, mark);
}

bool Grid::inside(int r, int c) const { return r >= 0 && r < R && c >= 0 && c < C; }

Grid::Grid(int rows, int cols, const char* pattern) : R(rows), C(cols), cells(new char*[rows]), best(-1) {
    for (int r = 0; r < R; r++) {
        cells[r] = new char[C];
        for (int c = 0; c < C; c++) cells[r][c] = pattern[r * C + c];
    }
}

Grid::~Grid() {
    for (int r = 0; r < R; r++) delete[] cells[r];
    delete[] cells;
    cout << "grid freed" << endl;
}

int Grid::largest() const { return best; }

char Grid::get(int r, int c) const { return inside(r, c) ? cells[r][c] : '?'; }

void Grid::show() const {
    for (int r = 0; r < R; r++) {
        for (int c = 0; c < C; c++) cout << get(r, c);
        cout << '\n';
    }
}

int main() {
    const char* pat =
        "##..#"
        "#..##"
        "..#.."
        "###.#"
        "....#";
    Grid g(5, 5, pat);
    cout << "before largest=" << g.largest() << endl;
    int n = g.countRegions();
    g.show();
    cout << "regions=" << n << " largest=" << g.largest() << " outside=" << g.get(9, 9) << endl;
    return 0;
}
